// === Tab: mySketch ===
let pts;

function setup() {
	createCanvas(600, 600);

	pts = [];
	for (let i = 0; i < 25; i++) {
		const x = random(width);
		const s = random(width * 0.1, width * 0.3)
		const y = random(height, height *2);
		const dy = random(1, 3);
		pts.push({x, y, s, dy})
	}
}


function draw() {
	background("white")

	noFill()
	stroke(0);
	for (let p of pts) {
		strokeWeight(p.s)
		point(p.x, p.y)
		p.x += random(-5, 5)
		p.x = lerp(p.x, width/2, 0.003)
		p.y -= p.dy;
		if (p.y < -p.s) p.y = height + p.s
	}

	filter(BLUR, 10);
	filter(THRESHOLD);

	// // noLoop() removed for animation
}
